import assert from 'node:assert/strict';
import test from 'node:test';
import { lintTicket } from '@/scripts/ticket-lint.mjs';

// docs/tickets.md template, criteria and size rules; #107 packed eleven unproven criteria
// across native, startup and copy work, which these checks refuse.
const ticket = ({
  size = 'Migrations 0 · New screens 1 · Native modules 0 · Proofs 3',
  criteria = [
    '- [ ] The history list shows archived workouts - Evidence: repository test'
  ],
  extra = ''
} = {}) =>
  [
    '> _This was generated by AI during triage._',
    '## What to build',
    'Show archived workouts.',
    extra,
    '## Ownership',
    '- Owns: restore confirmation sheet',
    '- Out of scope: restore (#123)',
    '## Size',
    size,
    '## Acceptance criteria',
    ...criteria
  ].join('\n');

test('a template-shaped ticket passes', () => {
  assert.deepEqual(lintTicket(ticket()), []);
  assert.deepEqual(
    lintTicket(ticket({ extra: '## Rules\n- x\n## Current state\n- y' })),
    []
  );
});

test('sections are required, unique and known', () => {
  const problems = lintTicket('## What to build\nx\n## Plan\ny');

  for (const expected of [
    'Missing section: ## Ownership',
    'Missing section: ## Size',
    'Missing section: ## Acceptance criteria',
    'Unknown section: ## Plan'
  ]) {
    assert.ok(problems.includes(expected), expected);
  }
});

test('size limits refuse an oversized slice', () => {
  assert.deepEqual(
    lintTicket(
      ticket({
        size: 'Migrations 1 · New screens 4 · Native modules 2 · Proofs 9'
      })
    ),
    [
      'New screens 4 passes its limit 3: split',
      'Native modules 2 passes its limit 1: split',
      'Proofs 9 passes its limit 6: split',
      'A ticket with a migration adds no screens: split data from screens'
    ]
  );
  assert.ok(
    lintTicket(ticket({ size: 'Migrations 0' })).includes(
      'Size line needs "Proofs <n>"'
    )
  );
});

test('criteria hold one outcome, one proof and no done-definition steps', () => {
  assert.deepEqual(
    lintTicket(
      ticket({
        criteria: [
          '- [ ] Archive saves',
          '- [ ] Archive saves; the list updates - Evidence: test',
          '- [ ] Validation checks pass - Evidence: tsc',
          '- [ ] A new ESLint rule refuses namespace imports - Evidence: lint test'
        ]
      })
    ),
    [
      'Criterion 1 needs exactly one " - Evidence: <proof>"',
      'Criterion 2 joins outcomes with ";": split it',
      'Criterion 3 restates the done definition (checks, push, evidence, close)'
    ]
  );
  const many = Array.from(
    { length: 9 },
    (_, i) => `- [ ] Outcome ${i} - Evidence: test`
  );
  assert.deepEqual(lintTicket(ticket({ criteria: many })), [
    '9 criteria pass 8: the ticket holds two slices'
  ]);
});

test('ownership names owners and What to build stays short', () => {
  const body = ticket({ extra: 'word '.repeat(151) }).replace(
    'restore (#123)',
    'restore'
  );
  assert.deepEqual(lintTicket(body), [
    'What to build has 154 words; the limit is 150',
    'Out of scope names the issue that owns each item, or reads "none"'
  ]);
});
